// src/modules/home/crafted-defenses/index.ts
var allCraftedDefenses = [
  hookTowerData,
  flameSpinnerData,
  crusherMortarData,
  heroBellData,
  bombHiveData,
  lightBeamData,
  roasterData,
  airBombsData,
  lavaLauncherData
];
var HomeVillageCraftedDefenses = class _HomeVillageCraftedDefenses extends QueryBase {
  constructor(data2 = allCraftedDefenses) {
    super(data2);
  }
  hookTower() {
    return new _HomeVillageCraftedDefenses([hookTowerData]);
  }
  flameSpinner() {
    return new _HomeVillageCraftedDefenses([flameSpinnerData]);
  }
  crusherMortar() {
    return new _HomeVillageCraftedDefenses([crusherMortarData]);
  }
  heroBell() {
    return new _HomeVillageCraftedDefenses([heroBellData]);
  }
  bombHive() {
    return new _HomeVillageCraftedDefenses([bombHiveData]);
  }
  lightBeam() {
    return new _HomeVillageCraftedDefenses([lightBeamData]);
  }
  roaster() {
    return new _HomeVillageCraftedDefenses([roasterData]);
  }
  airBombs() {
    return new _HomeVillageCraftedDefenses([airBombsData]);
  }
  lavaLauncher() {
    return new _HomeVillageCraftedDefenses([lavaLauncherData]);
  }
  /** Filter to a specific crafting phase (1, 2, 3, …). */
  byPhase(phase) {
    return new _HomeVillageCraftedDefenses(this.data.filter((d) => d.craftingPhase === phase));
  }
  /** Filter to defenses in the currently active crafting phase. */
  current() {
    return new _HomeVillageCraftedDefenses(this.data.filter((d) => d.isCurrent));
  }
  /** Filter to defenses from previous (retired) crafting phases. */
  former() {
    return new _HomeVillageCraftedDefenses(this.data.filter((d) => !d.isCurrent));
  }
  /** Filter by target type. */
  byTargetType(type) {
    return new _HomeVillageCraftedDefenses(this.data.filter((d) => d.targetType === type));
  }
};

