var allDefenses = [
  cannonData,
  archerTowerData,
  mortarData,
  airDefenseData,
  wizardTowerData,
  airSweeperData,
  hiddenTeslaData,
  bombTowerData,
  xBowData,
  infernoTowerData,
  eagleArtilleryData,
  scattershotData,
  buildersHutData,
  spellTowerData,
  monolithData,
  multiArcherTowerData,
  firespitterData,
  multiGearTowerData,
  revengeTowerData,
  ricochetCannonData,
  superWizardTowerData,
  craftingStationData
];
var HomeVillageDefenses = class _HomeVillageDefenses extends QueryBase {
  constructor(data2 = allDefenses) {
    super(data2);
  }
  cannon() {
    return new _HomeVillageDefenses([cannonData]);
  }
  archerTower() {
    return new _HomeVillageDefenses([archerTowerData]);
  }
  mortar() {
    return new _HomeVillageDefenses([mortarData]);
  }
  airDefense() {
    return new _HomeVillageDefenses([airDefenseData]);
  }
  wizardTower() {
    return new _HomeVillageDefenses([wizardTowerData]);
  }
  airSweeper() {
    return new _HomeVillageDefenses([airSweeperData]);
  }
  hiddenTesla() {
    return new _HomeVillageDefenses([hiddenTeslaData]);
  }
  bombTower() {
    return new _HomeVillageDefenses([bombTowerData]);
  }
  xBow() {
    return new _HomeVillageDefenses([xBowData]);
  }
  infernoTower() {
    return new _HomeVillageDefenses([infernoTowerData]);
  }
  eagleArtillery() {
    return new _HomeVillageDefenses([eagleArtilleryData]);
  }
  scattershot() {
    return new _HomeVillageDefenses([scattershotData]);
  }
  buildersHut() {
    return new _HomeVillageDefenses([buildersHutData]);
  }
  spellTower() {
    return new _HomeVillageDefenses([spellTowerData]);
  }
  monolith() {
    return new _HomeVillageDefenses([monolithData]);
  }
  multiArcherTower() {
    return new _HomeVillageDefenses([multiArcherTowerData]);
  }
  firespitter() {
    return new _HomeVillageDefenses([firespitterData]);
  }
  multiGearTower() {
    return new _HomeVillageDefenses([multiGearTowerData]);
  }
  revengeTower() {
    return new _HomeVillageDefenses([revengeTowerData]);
  }
  ricochetCannon() {
    return new _HomeVillageDefenses([ricochetCannonData]);
  }
  superWizardTower() {
    return new _HomeVillageDefenses([superWizardTowerData]);
  }
  craftingStation() {
    return new _HomeVillageDefenses([craftingStationData]);
  }
  /** Filter to a specific building by name (case-insensitive). */
  byBuilding(name) {
    const q = name.toLowerCase();
    return new _HomeVillageDefenses(this.data.filter((d) => d.name.toLowerCase() === q));
  }
  /**
   * Filter to buildings that have at least one level available at or before
   * the given Town Hall level.
   */
  byTownHall(level) {
    return new _HomeVillageDefenses(
      this.data.filter((d) => d.levels.some((l) => l.townHallRequired <= level))
    );
  }
  /** Filter by damage type of the normal mode (use 'none' for knockback-only buildings like Air Sweeper). Buildings without a normal mode (e.g. Spell Tower) are excluded. */
  byDamageType(type) {
    return new _HomeVillageDefenses(this.data.filter((d) => d.modes.normal?.damageType === type));
  }
  /** Filter to buildings that can be geared up (any gear-up mode). */
  hasGearUp() {
    return new _HomeVillageDefenses(this.data.filter((d) => d.gearUp !== void 0));
  }
};

