// src/modules/home/guardians/index.ts
var allGuardians = [longshotData, smasherData];
var HomeVillageGuardians = class _HomeVillageGuardians extends QueryBase {
  constructor(data2 = allGuardians) {
    super(data2);
  }
  longshot() {
    return new _HomeVillageGuardians([longshotData]);
  }
  smasher() {
    return new _HomeVillageGuardians([smasherData]);
  }
  /** Filter to a specific guardian variant by type (e.g. 'longshot', 'smasher'). */
  byGuardianType(type) {
    return new _HomeVillageGuardians(this.data.filter((g) => g.guardianType === type));
  }
  /**
   * Filter to guardians that have at least one level available at or before
   * the given Town Hall level.
   */
  byTownHall(level) {
    return new _HomeVillageGuardians(
      this.data.filter((g) => g.levels.some((l) => l.townHallRequired <= level))
    );
  }
};

