// src/modules/home/heroes/royal-champion/index.ts
var royalChampionData = royal_champion_default;

// src/modules/home/heroes/index.ts
var allHeroes = [
  barbarianKingData,
  archerQueenData,
  grandWardenData,
  royalChampionData,
  minionPrinceData,
  dragonDukeData
];
var HomeVillageHeroes = class _HomeVillageHeroes extends QueryBase {
  constructor(data2 = allHeroes) {
    super(data2);
  }
  barbarianKing() {
    return new _HomeVillageHeroes([barbarianKingData]);
  }
  archerQueen() {
    return new _HomeVillageHeroes([archerQueenData]);
  }
  grandWarden() {
    return new _HomeVillageHeroes([grandWardenData]);
  }
  royalChampion() {
    return new _HomeVillageHeroes([royalChampionData]);
  }
  dragonDuke() {
    return new _HomeVillageHeroes([dragonDukeData]);
  }
  minionPrince() {
    return new _HomeVillageHeroes([minionPrinceData]);
  }
  /** Filter to heroes that have at least one level available at or below the given Hero Hall level. */
  byHeroHall(level) {
    return new _HomeVillageHeroes(
      this.data.filter((h) => h.levels.some((l) => l.heroHallLevelRequired <= level))
    );
  }
};

