// src/modules/home/other/index.ts
var allOtherBuildings = [bobsHutData];
var HomeVillageHelperHut = class extends QueryBase {
  constructor(data2 = [helperHutData]) {
    super(data2);
  }
};
var HomeVillageLabAssistant = class extends QueryBase {
  constructor(data2 = [labAssistantData]) {
    super(data2);
  }
};
var HomeVillageBuildersApprentice = class extends QueryBase {
  constructor(data2 = [buildersApprenticeData]) {
    super(data2);
  }
};
var HomeVillageAlchemist = class extends QueryBase {
  constructor(data2 = [alchemistData]) {
    super(data2);
  }
};
var HomeVillageProspector = class extends QueryBase {
  constructor(data2 = [prospectorData]) {
    super(data2);
  }
};
var HomeVillageHelpers = class _HomeVillageHelpers extends QueryBase {
  constructor(data2 = [
    labAssistantData,
    buildersApprenticeData,
    alchemistData,
    prospectorData
  ]) {
    super(data2);
  }
  labAssistant() {
    return new HomeVillageLabAssistant([labAssistantData]);
  }
  buildersApprentice() {
    return new HomeVillageBuildersApprentice([buildersApprenticeData]);
  }
  alchemist() {
    return new HomeVillageAlchemist([alchemistData]);
  }
  prospector() {
    return new HomeVillageProspector([prospectorData]);
  }
  /** Filter to helpers unlocked at or before the given Town Hall level. */
  byTownHall(level) {
    return new _HomeVillageHelpers(this.data.filter((h) => h.townHallRequired <= level));
  }
};
var HomeVillageOtherBuildings = class _HomeVillageOtherBuildings extends QueryBase {
  constructor(data2 = allOtherBuildings) {
    super(data2);
  }
  bobsHut() {
    return new _HomeVillageOtherBuildings([bobsHutData]);
  }
  helperHut() {
    return new HomeVillageHelperHut([helperHutData]);
  }
  /** Returns a query over all helper units (Lab Assistant, Builder's Apprentice, Alchemist, Prospector). */
  helpers() {
    return new HomeVillageHelpers();
  }
  /** Filter to other buildings available (count > 0) at the given Town Hall level. */
  byTownHall(level) {
    return new _HomeVillageOtherBuildings(
      this.data.filter(
        (b) => b.availablePerTownHall.some((e) => e.townHallLevel === level && e.count > 0)
      )
    );
  }
};

