var allPets = [
  lassiData,
  electroOwlData,
  mightyYakData,
  unicornData,
  frostyData,
  diggyData,
  poisonLizardData,
  phoenixData,
  spiritFoxData,
  angryJellyData,
  sneezyData,
  greedyRavenData
];
var HomeVillagePets = class _HomeVillagePets extends QueryBase {
  constructor(data2 = allPets) {
    super(data2);
  }
  lassi() {
    return new _HomeVillagePets([lassiData]);
  }
  electroOwl() {
    return new _HomeVillagePets([electroOwlData]);
  }
  mightyYak() {
    return new _HomeVillagePets([mightyYakData]);
  }
  unicorn() {
    return new _HomeVillagePets([unicornData]);
  }
  frosty() {
    return new _HomeVillagePets([frostyData]);
  }
  diggy() {
    return new _HomeVillagePets([diggyData]);
  }
  poisonLizard() {
    return new _HomeVillagePets([poisonLizardData]);
  }
  phoenix() {
    return new _HomeVillagePets([phoenixData]);
  }
  spiritFox() {
    return new _HomeVillagePets([spiritFoxData]);
  }
  angryJelly() {
    return new _HomeVillagePets([angryJellyData]);
  }
  sneezy() {
    return new _HomeVillagePets([sneezyData]);
  }
  greedyRaven() {
    return new _HomeVillagePets([greedyRavenData]);
  }
  /** Filter to pets that are unlocked at or below the given Pet House level. */
  byPetHouse(level) {
    return new _HomeVillagePets(this.data.filter((p) => p.petHouseLevelRequired <= level));
  }
  /** Filter to pets that have at least one level available at or before the given Town Hall level. */
  byTownHall(level) {
    return new _HomeVillagePets(
      this.data.filter((p) => p.levels.some((l) => l.townHallRequired <= level))
    );
  }
};

