// src/modules/home/resource-buildings/index.ts
var HomeVillageClanCastle = class extends QueryBase {
  constructor(data2 = [clanCastleData]) {
    super(data2);
  }
};
var allResourceBuildings = [
  goldMineData,
  elixirCollectorData,
  darkElixirDrillData,
  goldStorageData,
  elixirStorageData,
  darkElixirStorageData
];
var HomeVillageResourceBuildings = class _HomeVillageResourceBuildings extends QueryBase {
  constructor(data2 = allResourceBuildings) {
    super(data2);
  }
  goldMine() {
    return new _HomeVillageResourceBuildings([goldMineData]);
  }
  elixirCollector() {
    return new _HomeVillageResourceBuildings([elixirCollectorData]);
  }
  darkElixirDrill() {
    return new _HomeVillageResourceBuildings([darkElixirDrillData]);
  }
  goldStorage() {
    return new _HomeVillageResourceBuildings([goldStorageData]);
  }
  elixirStorage() {
    return new _HomeVillageResourceBuildings([elixirStorageData]);
  }
  darkElixirStorage() {
    return new _HomeVillageResourceBuildings([darkElixirStorageData]);
  }
  clanCastle() {
    return new HomeVillageClanCastle([clanCastleData]);
  }
  /** Filter to resource buildings available (count > 0) at the given Town Hall level. */
  byTownHall(level) {
    return new _HomeVillageResourceBuildings(
      this.data.filter(
        (b) => b.availablePerTownHall.some((e) => e.townHallLevel === level && e.count > 0)
      )
    );
  }
};

