var allSiegeMachines = [
  wallWreckerData,
  battleBlimpData,
  stoneSlammerData,
  siegeBarracksData,
  logLauncherData,
  flameFlingerData,
  battleDrillData,
  troopLauncherData
];
var HomeVillageSiegeMachines = class _HomeVillageSiegeMachines extends QueryBase {
  constructor(data2 = allSiegeMachines) {
    super(data2);
  }
  wallWrecker() {
    return new _HomeVillageSiegeMachines([wallWreckerData]);
  }
  battleBlimp() {
    return new _HomeVillageSiegeMachines([battleBlimpData]);
  }
  stoneSlammer() {
    return new _HomeVillageSiegeMachines([stoneSlammerData]);
  }
  siegeBarracks() {
    return new _HomeVillageSiegeMachines([siegeBarracksData]);
  }
  logLauncher() {
    return new _HomeVillageSiegeMachines([logLauncherData]);
  }
  flameFlinger() {
    return new _HomeVillageSiegeMachines([flameFlingerData]);
  }
  battleDrill() {
    return new _HomeVillageSiegeMachines([battleDrillData]);
  }
  troopLauncher() {
    return new _HomeVillageSiegeMachines([troopLauncherData]);
  }
  /** Filter to siege machines unlocked at or below the given Workshop level. */
  byWorkshop(level) {
    return new _HomeVillageSiegeMachines(this.data.filter((m) => m.workshopLevelRequired <= level));
  }
  /** Filter to siege machines that have at least one level available at or before the given Town Hall level. */
  byTownHall(level) {
    return new _HomeVillageSiegeMachines(
      this.data.filter((m) => m.levels.some((l) => l.townHallRequired <= level))
    );
  }
};

