// src/modules/home/traps/index.ts
var allTraps = [
  bombData,
  springTrapData,
  giantBombData,
  airBombData,
  seekingAirMineData,
  skeletonTrapData,
  tornadoTrapData,
  gigaBombData
];
var HomeVillageTraps = class _HomeVillageTraps extends QueryBase {
  constructor(data2 = allTraps) {
    super(data2);
  }
  bomb() {
    return new _HomeVillageTraps([bombData]);
  }
  springTrap() {
    return new _HomeVillageTraps([springTrapData]);
  }
  giantBomb() {
    return new _HomeVillageTraps([giantBombData]);
  }
  airBomb() {
    return new _HomeVillageTraps([airBombData]);
  }
  seekingAirMine() {
    return new _HomeVillageTraps([seekingAirMineData]);
  }
  skeletonTrap() {
    return new _HomeVillageTraps([skeletonTrapData]);
  }
  tornadoTrap() {
    return new _HomeVillageTraps([tornadoTrapData]);
  }
  gigaBomb() {
    return new _HomeVillageTraps([gigaBombData]);
  }
  /** Filter to a specific trap by name (case-insensitive). */
  byTrap(name) {
    const q = name.toLowerCase();
    return new _HomeVillageTraps(this.data.filter((t) => t.name.toLowerCase() === q));
  }
  /** Filter to traps available (count > 0) at the given Town Hall level. */
  byTownHall(level) {
    return new _HomeVillageTraps(
      this.data.filter(
        (t) => t.availablePerTownHall.some((e) => e.townHallLevel === level && e.count > 0)
      )
    );
  }
  /** Filter by target type. */
  byTargetType(type) {
    return new _HomeVillageTraps(this.data.filter((t) => t.targetType === type));
  }
};

