var allWalls = [wallData];
var HomeVillageWalls = class _HomeVillageWalls extends QueryBase {
  constructor(data2 = allWalls) {
    super(data2);
  }
  wall() {
    return new _HomeVillageWalls([wallData]);
  }
  /** Filter to walls available (count > 0) at the given Town Hall level. */
  byTownHall(level) {
    return new _HomeVillageWalls(
      this.data.filter(
        (w) => w.availablePerTownHall.some((e) => e.townHallLevel === level && e.count > 0)
      )
    );
  }
};

