var BuilderBaseReinforcementCamp = class _BuilderBaseReinforcementCamp extends QueryBase {
  constructor(data2 = [reinforcementCampData]) {
    super(data2);
  }
  /**
   * Returns a new query with each camp's `instances` filtered to those
   * unlockable at or before the given Builder Hall level.
   */
  byBuilderHall(level) {
    return new _BuilderBaseReinforcementCamp(
      this.data.map((camp) => ({
        ...camp,
        instances: camp.instances.filter((i) => i.builderHallRequired <= level)
      }))
    );
  }
};
var BuilderBaseArmyCamp = class _BuilderBaseArmyCamp extends QueryBase {
  constructor(data2 = [armyCampData2]) {
    super(data2);
  }
  /**
   * Returns a new query with each camp's `instances` filtered to those
   * unlockable at or before the given Builder Hall level.
   * Mirrors how `byBuilderHall` on other buildings filters by level.
   */
  byBuilderHall(level) {
    return new _BuilderBaseArmyCamp(
      this.data.map((camp) => ({
        ...camp,
        instances: camp.instances.filter((i) => i.builderHallRequired <= level)
      }))
    );
  }
};
var allArmyBuildings2 = [
  builderBarracksData,
  armyCampData2,
  starLaboratoryData,
  battleMachineAltarData,
  battleCopterAltarData,
  reinforcementCampData,
  healingHutData
];
var BuilderBaseArmyBuildings = class _BuilderBaseArmyBuildings extends QueryBase {
  constructor(data2 = allArmyBuildings2) {
    super(data2);
  }
  builderBarracks() {
    return new _BuilderBaseArmyBuildings([builderBarracksData]);
  }
  armyCamp() {
    return new BuilderBaseArmyCamp();
  }
  starLaboratory() {
    return new _BuilderBaseArmyBuildings([starLaboratoryData]);
  }
  battleMachineAltar() {
    return new _BuilderBaseArmyBuildings([battleMachineAltarData]);
  }
  battleCopterAltar() {
    return new _BuilderBaseArmyBuildings([battleCopterAltarData]);
  }
  reinforcementCamp() {
    return new BuilderBaseReinforcementCamp();
  }
  healingHut() {
    return new _BuilderBaseArmyBuildings([healingHutData]);
  }
  /** Filter to army buildings available (count > 0) at the given Builder Hall level. */
  byBuilderHall(level) {
    return new _BuilderBaseArmyBuildings(
      this.data.filter(
        (b) => b.availablePerBuilderHall.some((e) => e.builderHallLevel === level && e.count > 0)
      )
    );
  }
};

