var battleMachineData = battle_machine_default;

// src/modules/builder/heroes/index.ts
var allHeroes2 = [battleMachineData, battleCopterData];
var BuilderBaseHeroes = class _BuilderBaseHeroes extends QueryBase {
  constructor(data2 = allHeroes2) {
    super(data2);
  }
  battleMachine() {
    return new _BuilderBaseHeroes([battleMachineData]);
  }
  battleCopter() {
    return new _BuilderBaseHeroes([battleCopterData]);
  }
  /** Filter to heroes that have at least one level available at or below the given Builder Hall level. */
  byBuilderHall(level) {
    return new _BuilderBaseHeroes(
      this.data.filter((h) => h.levels.some((l) => l.builderHallLevelRequired <= level))
    );
  }
};

