var allLeagues = builder_base_leagues_default;
var BuilderBaseLeagues = class _BuilderBaseLeagues extends QueryBase {
  /** Filter to leagues belonging to a specific group (e.g. `"Wood"`, `"Diamond"`). */
  byGroup(group) {
    return new _BuilderBaseLeagues(this.data.filter((l) => l.group === group));
  }
  /**
   * Filter leagues by a partial, case-insensitive name search.
   * e.g. `byName('Iron')` returns Iron III, Iron II, Iron I.
   *      `byName('Iron I')` returns only Iron I.
   */
  byName(query) {
    const q = query.toLowerCase();
    return new _BuilderBaseLeagues(this.data.filter((l) => l.name.toLowerCase().includes(q)));
  }
  /**
   * Return the league that contains the given trophy count, or `undefined` if out of range.
   * Diamond league matches any value ≥ 6200.
   */
  atTrophies(trophies) {
    return this.data.find(
      (l) => trophies >= l.trophyMin && (l.trophyMax === null || trophies <= l.trophyMax)
    );
  }
};
function allBuilderBaseLeagues() {
  return new BuilderBaseLeagues(allLeagues);
}

