// src/modules/builder/traps/index.ts
var allTraps2 = [pushTrapData, springTrapData2, mineData, megaMineData];
var BuilderBaseTraps = class _BuilderBaseTraps extends QueryBase {
  constructor(data2 = allTraps2) {
    super(data2);
  }
  pushTrap() {
    return new _BuilderBaseTraps([pushTrapData]);
  }
  springTrap() {
    return new _BuilderBaseTraps([springTrapData2]);
  }
  mine() {
    return new _BuilderBaseTraps([mineData]);
  }
  megaMine() {
    return new _BuilderBaseTraps([megaMineData]);
  }
  /** Filter to traps available (count > 0) at the given Builder Hall level. */
  byBuilderHall(level) {
    return new _BuilderBaseTraps(
      this.data.filter(
        (t) => t.availablePerBuilderHall.some((e) => e.builderHallLevel === level && e.count > 0)
      )
    );
  }
};

