// src/modules/builder/walls/index.ts
var allWalls2 = [wallData2];
var BuilderBaseWalls = class _BuilderBaseWalls extends QueryBase {
  constructor(data2 = allWalls2) {
    super(data2);
  }
  wall() {
    return new _BuilderBaseWalls([wallData2]);
  }
  /** Filter to walls available (count > 0) at the given Builder Hall level. */
  byBuilderHall(level) {
    return new _BuilderBaseWalls(
      this.data.filter(
        (w) => w.availablePerBuilderHall.some((e) => e.builderHallLevel === level && e.count > 0)
      )
    );
  }
};

// src/modules/builder/index.ts
var BuilderBase = class {
  /** Returns a query wrapping the Builder Hall entity. */
  builderHall() {
    return new BuilderBaseBuilderHall();
  }
  /** Returns a query over all stationary defenses (Cannon, etc.). */
  defenses() {
    return new BuilderBaseDefenses();
  }
  /** Returns a query over Builder Base traps. */
  traps() {
    return new BuilderBaseTraps();
  }
  /** Returns a query over Builder Base wall data. */
  walls() {
    return new BuilderBaseWalls();
  }
  /** Returns a query over Builder Base resource buildings. */
  resourceBuildings() {
    return new BuilderBaseResourceBuildings();
  }
  /** Returns a query over Builder Base army buildings. */
  armyBuildings() {
    return new BuilderBaseArmyBuildings();
  }
  /** Returns a query over other Builder Base buildings (Clock Tower, etc.). */
  otherBuildings() {
    return new BuilderBaseOtherBuildings();
  }
  /** Returns a query over Builder Base troops. */
  troops() {
    return new BuilderBaseTroops();
  }
  /** Returns a query over Builder Base heroes. */
  heroes() {
    return new BuilderBaseHeroes();
  }
  /** Returns a query over all Builder Base leagues. */
  leagues() {
    return allBuilderBaseLeagues();
  }
  /**
   * Computes the total number of upgradeable level slots available at a given Builder Hall level,
   * broken down by category. Useful for progress tracking and upgrade completion ratios.
   *
   * @param bhLevel - Builder Hall level (1–10)
   */
  levelCountAtBuilderHall(bhLevel) {
    const allStructures = [
      ...this.defenses().get(),
      ...this.armyBuildings().get(),
      ...this.resourceBuildings().get()
    ];
    const armyCampInstances = armyCampData2.instances.filter(
      (i) => i.builderHallRequired <= bhLevel
    ).length;
    const reinforcementCampInstances = reinforcementCampData.instances.filter(
      (i) => i.builderHallRequired <= bhLevel
    ).length;
    const structures = allStructures.reduce((sum, b) => sum + bhStructureCount(b, bhLevel), 0) + armyCampInstances + reinforcementCampInstances;
    const traps = this.traps().get().reduce(
      (sum, t) => sum + bhStructureCount(t, bhLevel),
      0
    );
    const starLab = this.armyBuildings().starLaboratory().first();
    const maxStarLabLevel = starLab.levels.filter((l) => l.builderHallRequired <= bhLevel).reduce((m, l) => Math.max(m, l.level), 0);
    const starLabCount = this.troops().get().reduce((sum, t) => {
      const maxLevel = t.levels.filter((l) => l.starLabRequired <= maxStarLabLevel).reduce((m, l) => Math.max(m, l.level), 0);
      return sum + maxLevel;
    }, 0);
    const heroes = this.heroes().get().reduce((sum, h) => {
      const maxLevel = h.levels.filter((l) => l.builderHallLevelRequired <= bhLevel).reduce((m, l) => Math.max(m, l.level), 0);
      return sum + maxLevel;
    }, 0);
    const wall = this.walls().wall().first();
    const wallCount = wall.availablePerBuilderHall.find((e) => e.builderHallLevel === bhLevel)?.count ?? 0;
    const maxWallLevel = wall.levels.filter((l) => l.builderHallRequired <= bhLevel).reduce((m, l) => Math.max(m, l.level), 0);
    const walls = wallCount * maxWallLevel;
    const total = structures + traps + starLabCount + heroes + walls;
    return { structures, traps, starLab: starLabCount, heroes, walls, total };
  }
};
function builder() {
  return new BuilderBase();
}

