// src/modules/clan-capital/leagues/index.ts
var allLeagues2 = clan_capital_leagues_default;
var ClanCapitalLeagues = class _ClanCapitalLeagues extends QueryBase {
  /** Filter to leagues belonging to a specific group (e.g. `"Gold"`, `"Master"`). */
  byGroup(group) {
    return new _ClanCapitalLeagues(this.data.filter((l) => l.group === group));
  }
  /**
   * Return the league that contains the given trophy count, or `undefined` if out of range.
   * Legend league matches any value ≥ 5000.
   */
  atTrophies(trophies) {
    return this.data.find(
      (l) => trophies >= l.trophyMin && (l.trophyMax === null || trophies <= l.trophyMax)
    );
  }
};
function allClanCapitalLeagues() {
  return new ClanCapitalLeagues(allLeagues2);
}

