var ClanCapitalTraps = class _ClanCapitalTraps extends QueryBase {
  constructor(data2 = allTraps3) {
    super(data2);
  }
  mine() {
    return new _ClanCapitalTraps([mineData2]);
  }
  megaMine() {
    return new _ClanCapitalTraps([megaMineData2]);
  }
  logTrap() {
    return new _ClanCapitalTraps([logTrapData]);
  }
  zapTrap() {
    return new _ClanCapitalTraps([zapTrapData]);
  }
  spearTrap() {
    return new _ClanCapitalTraps([spearTrapData]);
  }
  /** Filter to traps targeting the given type. */
  byTargetType(type) {
    return new _ClanCapitalTraps(this.data.filter((t) => t.targetType === type));
  }
  /** Filter to traps available in the given district. */
  byDistrict(district) {
    return new _ClanCapitalTraps(
      this.data.filter((t) => t.availablePerDistrict.some((e) => e.district === district))
    );
  }
};

