// src/modules/clan-capital/index.ts
var ClanCapital = class {
  capitalHall() {
    return new ClanCapitalCapitalHall();
  }
  districtHall() {
    return new ClanCapitalDistrictHall();
  }
  /** Returns a query over all Clan Capital stationary defenses. */
  defenses() {
    return new ClanCapitalDefenses();
  }
  /** Returns a query over all Clan Capital army buildings. */
  armyBuildings() {
    return new ClanCapitalArmyBuildings();
  }
  /** Returns a query over Clan Capital other buildings (houses, etc.). */
  other() {
    return new ClanCapitalOther();
  }
  /** Returns a query over all Clan Capital spells. */
  spells() {
    return new ClanCapitalSpells();
  }
  /** Returns a query over all Clan Capital troops. */
  troops() {
    return new ClanCapitalTroops();
  }
  /** Returns a query over all Clan Capital traps. */
  traps() {
    return new ClanCapitalTraps();
  }
  /** Returns a query over Clan Capital wall data. */
  walls() {
    return new ClanCapitalWalls();
  }
  /** Returns a query over all Clan Capital Raid Weekend leagues. */
  leagues() {
    return allClanCapitalLeagues();
  }
  /** Returns Forge data — daily forge, auto forge, forge rates, available slots, and crafting time. */
  forge() {
    return new ClanCapitalForge();
  }
  /**
   * Computes the total number of upgradeable level slots available at a given Capital Hall level,
   * broken down by district/zone (structures + walls) and top-level totals for troops and spells.
   *
   * @param capitalHallLevel - Capital Hall level (1–10)
   */
  levelCountAtClanCapital(capitalHallLevel) {
    const allDistrictBuildings = [
      ...this.defenses().get(),
      ...this.armyBuildings().get(),
      ...this.armyBuildings().barracks().get(),
      ...this.armyBuildings().spellFactories().get(),
      ...this.traps().get()
    ];
    const capitalPeakBuildings = this.defenses().get().filter(
      (b) => b.availablePerCapitalHall && b.availablePerCapitalHall.some((e) => e.count > 0)
    ).map((b) => b);
    const wall = this.walls().wall().first();
    const dhLevels = {
      barbarianCamp: ccMaxDHLevel(districtHallData, "barbarianCamp", capitalHallLevel),
      wizardValley: ccMaxDHLevel(districtHallData, "wizardValley", capitalHallLevel),
      balloonLagoon: ccMaxDHLevel(districtHallData, "balloonLagoon", capitalHallLevel),
      buildersWorkshop: ccMaxDHLevel(districtHallData, "buildersWorkshop", capitalHallLevel),
      dragonCliffs: ccMaxDHLevel(districtHallData, "dragonCliffs", capitalHallLevel),
      golemQuarry: ccMaxDHLevel(districtHallData, "golemQuarry", capitalHallLevel),
      skeletonPark: ccMaxDHLevel(districtHallData, "skeletonPark", capitalHallLevel),
      goblinMines: ccMaxDHLevel(districtHallData, "goblinMines", capitalHallLevel)
    };
    const cpStructures = ccCapitalPeakStructures(capitalPeakBuildings, capitalHallLevel);
    const cpWalls = ccCapitalPeakWalls(wall, capitalHallLevel);
    const capitalPeak = {
      structures: cpStructures,
      walls: cpWalls,
      total: cpStructures + cpWalls
    };
    const barbarianCamp = ccDistrictCounts(
      allDistrictBuildings,
      wall,
      "barbarianCamp",
      dhLevels.barbarianCamp
    );
    const wizardValley = ccDistrictCounts(
      allDistrictBuildings,
      wall,
      "wizardValley",
      dhLevels.wizardValley
    );
    const balloonLagoon = ccDistrictCounts(
      allDistrictBuildings,
      wall,
      "balloonLagoon",
      dhLevels.balloonLagoon
    );
    const buildersWorkshop = ccDistrictCounts(
      allDistrictBuildings,
      wall,
      "buildersWorkshop",
      dhLevels.buildersWorkshop
    );
    const dragonCliffs = ccDistrictCounts(
      allDistrictBuildings,
      wall,
      "dragonCliffs",
      dhLevels.dragonCliffs
    );
    const golemQuarry = ccDistrictCounts(
      allDistrictBuildings,
      wall,
      "golemQuarry",
      dhLevels.golemQuarry
    );
    const skeletonPark = ccDistrictCounts(
      allDistrictBuildings,
      wall,
      "skeletonPark",
      dhLevels.skeletonPark
    );
    const goblinMines = ccDistrictCounts(
      allDistrictBuildings,
      wall,
      "goblinMines",
      dhLevels.goblinMines
    );
    const globalMaxDHLevel = Math.max(...Object.values(dhLevels));
    const troopDistrictDH = {};
    for (const barracks of this.armyBuildings().barracks().get()) {
      const district = barracks.availablePerDistrict[0]?.district;
      if (district && barracks.troopUnlocked) {
        troopDistrictDH[barracks.troopUnlocked] = dhLevels[district] ?? 0;
      }
    }
    const spellDistrictDH = {};
    for (const factory of this.armyBuildings().spellFactories().get()) {
      const district = factory.availablePerDistrict[0]?.district;
      if (district && factory.spellUnlocked) {
        spellDistrictDH[factory.spellUnlocked] = dhLevels[district] ?? 0;
      }
    }
    const troops = this.troops().get().reduce((sum, t) => {
      const dhLevel = troopDistrictDH[t.name] ?? 0;
      const maxLevel = t.levels.filter((l) => l.districtHallRequired <= dhLevel).reduce((m, l) => Math.max(m, l.level), 0);
      return sum + maxLevel;
    }, 0);
    const spells = this.spells().get().reduce((sum, s) => {
      const dhLevel = spellDistrictDH[s.name] ?? globalMaxDHLevel;
      const maxLevel = s.levels.filter((l) => l.districtHallRequired <= dhLevel).reduce((m, l) => Math.max(m, l.level), 0);
      return sum + maxLevel;
    }, 0);
    const total = capitalPeak.total + barbarianCamp.total + wizardValley.total + balloonLagoon.total + buildersWorkshop.total + dragonCliffs.total + golemQuarry.total + skeletonPark.total + goblinMines.total + troops + spells;
    return {
      capitalPeak,
      barbarianCamp,
      wizardValley,
      balloonLagoon,
      buildersWorkshop,
      dragonCliffs,
      golemQuarry,
      skeletonPark,
      goblinMines,
      troops,
      spells,
      total
    };
  }
};
function clanCapital() {
  return new ClanCapital();
}

// src/modules/calculators/utils.ts
function toTotalSeconds(t) {
  return t.days * 86400 + t.hours * 3600 + t.minutes * 60 + t.seconds;
}
function fromTotalSeconds(s) {
  const total = Math.max(0, Math.floor(s));
  return {
    days: Math.floor(total / 86400),
    hours: Math.floor(total % 86400 / 3600),
    minutes: Math.floor(total % 3600 / 60),
    seconds: total % 60
  };
}
function subtractHours(time, hours) {
  return fromTotalSeconds(toTotalSeconds(time) - hours * 3600);
}

// src/modules/calculators/boost/index.ts
var BuildBoostCalculator = class {
  // ── Time reduction ──────────────────────────────────────────────────────────
  /** Apply a Builder Boost to reduce build time by the given tier percentage (10, 15, or 20). */
  builderBoost(time, tier) {
    return fromTotalSeconds(toTotalSeconds(time) * (1 - tier / 100));
  }
  /** Apply a Research Boost to reduce research time by the given tier percentage (10, 15, or 20). */
  researchBoost(time, tier) {
    return fromTotalSeconds(toTotalSeconds(time) * (1 - tier / 100));
  }
  // ── Cost reduction ──────────────────────────────────────────────────────────
  /**
   * Apply a Builder Boost to reduce a build cost (Gold, Elixir, or Dark Elixir)
   * by the given tier percentage (10, 15, or 20). Returns the reduced cost, floored.
   */
  builderBoostCost(cost, resource, tier) {
    void resource;
    return Math.floor(cost * (1 - tier / 100));
  }
  /**
   * Apply a Research Boost to reduce a research cost (Gold, Elixir, or Dark Elixir)
   * by the given tier percentage (10, 15, or 20). Returns the reduced cost, floored.
   */
  researchBoostCost(cost, resource, tier) {
    void resource;
    return Math.floor(cost * (1 - tier / 100));
  }
};

// src/modules/calculators/clock-tower/index.ts
var levels = clock_tower_default.levels;
function levelData(level) {
  return levels[level - 1];
}
var ClockTowerCalculator = class {
  /**
   * Apply one full Clock Tower activation at the given level.
   * Reduces remaining build time by the `timeGainedMinutes` for that level.
   * Result is clamped to zero.
   */
  boost(time, level) {
    const { timeGainedMinutes } = levelData(level);
    return fromTotalSeconds(toTotalSeconds(time) - timeGainedMinutes * 60);
  }
  /**
   * Apply a Clock Tower Potion (fixed 30-minute run) at the given level.
   * Time saved = floor(timeGainedMinutes × 30 / boostDurationMinutes).
   * Result is clamped to zero.
   */
  potion(time, level) {
    const { boostDurationMinutes, timeGainedMinutes } = levelData(level);
    const minutesSaved = Math.floor(timeGainedMinutes * 30 / boostDurationMinutes);
    return fromTotalSeconds(toTotalSeconds(time) - minutesSaved * 60);
  }
};

// src/modules/calculators/gems/index.ts
var TIERS = [
  { seconds: 0, gems: 0 },
  { seconds: 60, gems: 1 },
  { seconds: 3600, gems: 20 },
  { seconds: 86400, gems: 260 },
  { seconds: 604800, gems: 1e3 }
];
var GemsCalculator = class {
  cost(time) {
    const s = toTotalSeconds(time);
    if (s <= 0) return 0;
    if (s < 60) return 1;
    for (let i = 1; i < TIERS.length; i++) {
      if (s <= TIERS[i].seconds) {
        const t0 = TIERS[i - 1];
        const t1 = TIERS[i];
        const progress = (s - t0.seconds) / (t1.seconds - t0.seconds);
        return Math.floor(t0.gems + progress * (t1.gems - t0.gems));
      }
    }
    const last = TIERS[TIERS.length - 1];
    const prev = TIERS[TIERS.length - 2];
    const ratePerSecond = (last.gems - prev.gems) / (last.seconds - prev.seconds);
    return Math.floor(last.gems + (s - last.seconds) * ratePerSecond);
  }
};

// src/modules/calculators/helpers/index.ts
var GOLD_ELIXIR_TO_DE_RATE = 150;
var HelpersCalculator = class {
  /**
   * Lab Assistant — reduces remaining research time by the helper's `workRate` at the given level
   * (workRate = hours of lab progress completed in 60 min of real time).
   */
  labAssistant(time, level) {
    const lvl = lab_assistant_default.levels.find((l) => l.level === level);
    return subtractHours(time, lvl.workRate);
  }
  /**
   * Builder's Apprentice — reduces remaining build time by the helper's `workRate` at the given level.
   * Note: does not boost the Apprentice's own build queue.
   */
  buildersApprentice(time, level) {
    const lvl = builders_apprentice_default.levels.find((l) => l.level === level);
    return subtractHours(time, lvl.workRate);
  }
  /**
   * Alchemist — converts Gold or Elixir to Dark Elixir at a rate of 150:1,
   * with a bonus percentage applied on top at the given level.
   * Input is capped at the level's `goldElixirConversionMax`.
   */
  alchemist(goldOrElixir, level) {
    const lvl = alchemist_default.levels.find((l) => l.level === level);
    const input = Math.min(goldOrElixir, lvl.goldElixirConversionMax);
    const base = Math.floor(input / GOLD_ELIXIR_TO_DE_RATE);
    const bonus = Math.floor(base * lvl.conversionBonusPercent / 100);
    return { input, base, bonus, total: base + bonus };
  }
  /**
   * Prospector — returns the maximum daily ore conversion amounts at the given level.
   */
  prospector(level) {
    const lvl = prospector_default.levels.find((l) => l.level === level);
    return {
      shinyOre: lvl.shinyOreConversionMax,
      glowyOre: lvl.glowyOreConversionMax,
      starryOre: lvl.starryOreConversionMax
    };
  }
};

// src/modules/calculators/potions/index.ts
var PotionsCalculator = class {
  /** Builder Potion: 10× builder speed for 60 min → reduces remaining build time by 10 hours. */
  builderPotion(time) {
    return subtractHours(time, 10);
  }
  /** Research Potion: 24× lab speed for 60 min → reduces remaining research time by 24 hours. */
  researchPotion(time) {
    return subtractHours(time, 24);
  }
  /** Pet Potion: 24× pet house speed for 60 min → reduces remaining pet upgrade time by 24 hours. */
  petPotion(time) {
    return subtractHours(time, 24);
  }
  /** Builder Bite: 2× builder speed for 60 min → reduces remaining build time by 2 hours. */
  builderBite(time) {
    return subtractHours(time, 2);
  }
  /** Study Soup: 4× lab speed for 60 min → reduces remaining research time by 4 hours. */
  studySoup(time) {
    return subtractHours(time, 4);
  }
};

// src/modules/calculators/index.ts
var Calculators = class {
  /** Build time and cost boost calculations (Builder Boost, Research Boost). */
  boost() {
    return new BuildBoostCalculator();
  }
  /** Gem cost calculator — converts build/research time into gem cost. */
  gems() {
    return new GemsCalculator();
  }
  /** Helper Hut helper calculations (Lab Assistant, Builder's Apprentice, Alchemist, Prospector). */
  helpers() {
    return new HelpersCalculator();
  }
  /** Time-reduction potion and snack calculations. */
  potions() {
    return new PotionsCalculator();
  }
  /** Clock Tower boost and potion calculations (time saved per level). */
  clockTower() {
    return new ClockTowerCalculator();
  }
};
function calculators() {
  return new Calculators();
}

