// src/modules/clan/war/index.ts
var allMaxWarBaseLoot = war_default.maxWarBaseLoot;
var allWarBonus = war_default.warBonus;
var allMaxWarBaseOre = war_default.maxWarBaseOre;
var ClanWar = class {
  /** Maximum available loot in an enemy war base, indexed by Town Hall level (TH3–18). */
  maxWarBaseLoot() {
    return allMaxWarBaseLoot;
  }
  /** Maximum available ore in an enemy war base, indexed by Town Hall level (TH8–18). */
  maxWarBaseOre() {
    return allMaxWarBaseOre;
  }
  /** War bonus tiers, grouped by clan level range. */
  warBonus() {
    return allWarBonus;
  }
  /**
   * Return the war bonus tier that applies to the given clan level.
   * Returns `undefined` if the clan level is below 1.
   */
  bonusTierForClanLevel(clanLevel) {
    return allWarBonus.find((tier) => {
      if (clanLevel < tier.minClanLevel) return false;
      if (tier.maxClanLevel === void 0) return true;
      return clanLevel <= tier.maxClanLevel;
    });
  }
};
function createClanWar() {
  return new ClanWar();
}

// src/modules/clan/index.ts
var Clan = class {
  /** Clan level progression — XP requirements, badges, and perks per level. */
  levels() {
    return createClanLevels();
  }
  /** Clan labels that can be displayed on a clan's profile. */
  labels() {
    return createClanLabels();
  }
  /** Clan war data — max base loot, war bonuses, and ore per Town Hall level. */
  war() {
    return createClanWar();
  }
};
function clan() {
  return new Clan();
}

