// src/modules/achievements/index.ts
var allAchievements = achievements_default.achievements;
var Achievements = class _Achievements extends QueryBase {
  /** Filter to achievements for a specific base (home, builder, clan-capital). */
  byBase(base) {
    return new _Achievements(this.data.filter((a) => a.base === base));
  }
  /** Filter to achievements that involve the given data description (case-insensitive substring). */
  byDataInvolved(keyword) {
    const q = keyword.toLowerCase();
    return new _Achievements(this.data.filter((a) => a.dataInvolved.toLowerCase().includes(q)));
  }
  /** Filter to achievements that have exactly the given number of tiers. */
  byTierCount(count) {
    return new _Achievements(this.data.filter((a) => a.tiers.length === count));
  }
};
function achievements() {
  return new Achievements(allAchievements);
}

